public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    long min = 0L;
    long passengers = 0L;

    for(int i = 0; i < N; i++) {
        long A = sc.nextLong();
        passengers += A;
        if(passengers < min) {
            min = passengers;
        }
    }

    long ans;
    if(min < 0) {
        ans = -min;
    } else {
        ans = 0;
    }
    System.out.println(ans);
}
